  "claims": [
    {
      "claim": "The query contains a quinolin-2(1H)-one and a piperazine/tertiary-amide architecture, motifs present in rebamipide (human F <10%) and nintedanib (human F ~4.7–5%), respectively; these are the closest structural anchors among the gold contexts.",
      "card_ids": ["C11","C01"]
    },
    {
      "claim": "Transferable human absolute oral bioavailability measurements for structurally similar high-MW, high-TPSA, predominantly ionized compounds are consistently below 20%: nintedanib ~4.7–5%, remikiren 0.2–0.3%, DX-9065a 2–3%, melagatran 3–7% (0.9% fed), astemizole ~3%, rebamipide <10%, and MK-458 ~4–5%.",
      "card_ids": ["C01","C03","C05","C07","C10","C11","C14","C16","C17","C20","C02"]
    },
    {
      "claim": "L2 context reinforces low F: remikiren <1.0% at 200 mg oral; DX-9065a 5–10% in animals, 5–12% in baboons, and 10.8±2.0% in fasted rats; melagatran-class peptidomimetics are not orally bioavailable due to poor enteral absorption and presystemic hepatic extraction; PHNO is low; DX-9065 capsule is limited in the fasted state.",
      "card_ids": ["C23","C28","C31","C32","C35","C36","C39"]
    },
    {
      "claim": "L6 hepatic clearance/metabolic-stability records are for unrelated reference molecules (imatinib, rebamipide, DMP, MK-0974, CU03, lipophilic compound 1, azelastine, R-VK4-116) and include both high and low clearance values; they do not provide query-specific hepatic first-pass evidence. Rebamipide's low human F coexists with low measured hepatic 8-hydroxylation clearance (up to 11 µL/min/kg; CYP3A4 CLint 3.33 µL/min/mg), so low F in that anchor is not explained by high hepatic clearance.",
      "card_ids": ["C76","C82","C11"]
    },
    {
      "claim": "No affirmative query-specific evidence supports F >= 20%; the low prediction remains supported by transferable human low-F outcomes and the query's large, highly ionized, high-TPSA structure.",
      "card_ids": ["C01","C03","C05","C07","C10","C11","C14","C16","C17","C20","C02"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C76","C77","C78","C79","C80","C81","C82","C83","C84","C85","C86","C87"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule.",
    "No query-specific oral AUC/Cmax or IV comparator data are available.",
    "No query-specific intestinal permeability, solubility, dissolution, efflux, or intestinal metabolism data are available.",
    "No query-specific hepatic clearance or metabolic stability data are available; L6 records are for unrelated reference molecules.",
    "First-pass hepatic metabolism and clearance for the query remain unmeasured.",
    "Formulation effects on oral exposure are unknown."
  ],
  "decision_summary": "Predicted low (F < 20%) because multiple transferable human low-F contexts for structurally similar high-MW, highly ionized, high-TPSA compounds support poor oral bioavailability. L6 hepatic clearance/metabolic-stability records are not query-specific and include mixed clearance values; they provide no affirmative query-specific evidence and do not change the prior low decision. Confidence remains moderate due to the absence of direct query PK data."
}

